// Shared pure decisions embedded into n8n Code nodes by build.py.
function scope(episodes,choice,now) {
 const aired=episodes.filter(e=>Number.isSafeInteger(e.id)&&e.id>0&&Number.isInteger(e.seasonNumber)&&e.seasonNumber>0&&Number.isFinite(Date.parse(e.airDateUtc))&&Date.parse(e.airDateUtc)<=now);
 if(choice==='all')return aired;
 let season;
 if(choice==='latest')season=Math.max(0,...aired.map(e=>e.seasonNumber));
 else if(/^season_[1-9][0-9]{0,3}$/.test(choice))season=Number(choice.slice(7));
 else throw new Error('Invalid season choice');
 return aired.filter(e=>e.seasonNumber===season);
}
function transition(row,actor,now) {
 if(!row||!['discord','telegram'].includes(row.source)||['source','userId','destinationId'].some(k=>row[k]!==actor[k]))throw new Error('Not your request');
 if(!Number.isFinite(Date.parse(row.expiresAt))||Date.parse(row.expiresAt)<=now)throw new Error('Request expired');
 if(!['preview','scope','seasons'].includes(row.state))throw new Error('Already handled');
 if(actor.action==='cancel')return 'cancelled';
 if(row.state==='preview'&&actor.action==='confirm')return row.mediaType==='tv'?'scope':'processing';
 if(row.mediaType==='tv'&&row.state==='scope'&&actor.action==='choose')return 'seasons';
 if(row.mediaType==='tv'&&row.state==='seasons'&&/^page_[0-9]{1,3}$/.test(actor.action))return 'seasons';
 if(row.mediaType==='tv'&&row.state==='scope'&&['latest','all'].includes(actor.action))return 'processing';
 if(row.mediaType==='tv'&&row.state==='seasons'&&/^season_[1-9][0-9]{0,3}$/.test(actor.action))return 'processing';
 throw new Error('Stale or invalid choice');
}
if(typeof module!=='undefined')module.exports={scope,transition};

const row=$input.first().json,a=$('Action Input').first().json;try {const state=transition(row,a,Date.now());return [{json:{row,state,choice:a.action,claimId:String($execution.id)}}];}catch{return [{json:{version:1,status:'notice',text:'This choice is expired, already handled, or belongs to another requester. Send a new request if needed.'}}];}

const r=$json;
if(r.version)return [{json:r}];
const notice=text=>[{json:{version:1,status:'notice',text}}];
if(!r.id)return notice('Unable to prepare that request. Please try again.');
if(r.state==='cancelled')return notice('Request cancelled. Nothing was downloaded.');
if(!['preview','scope','seasons'].includes(r.state))return notice('This request was already handled. Send a new request if needed.');
if(Date.parse(r.expiresAt)<=Date.now())return notice('This request expired. Please send it again.');
const m=JSON.parse(r.mediaJson);
const header=(r.mediaType==='movie'?'🎬 ':'📺 ')+m.title+(m.year?' ('+m.year+')':'');
let choices=[],text=header;
if(r.state==='preview'){
 text+='\n\n'+String(m.overview||'No description available.').slice(0,450)+'\n\nIs this the correct '+(r.mediaType==='movie'?'movie':'series')+'?';
 choices=[{label:'Confirm',action:'confirm'},{label:'Cancel',action:'cancel'}];
}else if(r.state==='scope'){
 text+='\n\nWhich episodes would you like?\nLatest means the newest season with aired episodes. Specials and future episodes are excluded.';
 choices=[{label:'Latest season',action:'latest'},{label:'Choose a season',action:'choose'},{label:'All seasons',action:'all'},{label:'Cancel',action:'cancel'}];
}else{
 const seasons=[...new Set((m.seasons||[]).map(s=>s.seasonNumber).filter(s=>Number.isInteger(s)&&s>0&&s<=9999))].sort((a,b)=>a-b);
 const page=/^page_[0-9]+$/.test(r.choice||'')?Number(r.choice.slice(5)):0;
 text+='\n\nChoose a season. Only aired episodes will be requested.';
 choices=seasons.slice(page*20,page*20+20).map(s=>({label:'Season '+s,action:'season_'+s}));
 if(page>0)choices.push({label:'Previous',action:'page_'+(page-1)});
 if((page+1)*20<seasons.length)choices.push({label:'Next',action:'page_'+(page+1)});
 choices.push({label:'Cancel',action:'cancel'});
}
const poster=(m.images||[]).find(x=>x.coverType==='poster');
const url=poster?.remoteUrl||poster?.url;
const out={version:1,status:'confirmation',text,pendingId:String(r.id),choices};
if(typeof url==='string'&&url.length<=2048&&/^https:\/\/(image\.tmdb\.org|artworks\.thetvdb\.com)\/[A-Za-z0-9_./%~-]+$/.test(url))out.posterUrl=url;
return [{json:out}];
